sys_script_include.script:
var GetSystemProperties = Class.create();
GetSystemProperties.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    getProperties: function() {
        var propertyName = 'Questionnariepart'; // Replace with actual system property name
        var gr = new GlideRecord('sys_properties');
        gr.addQuery('name', propertyName);
        gr.query();

        if (gr.next()) {
            var propertyValue = gr.getValue('value'); // Get JSON stored in sys_property
            gs.info("System Property Retrieved: " + propertyValue); // Logging for confirmation
            return propertyValue;
        }
        gs.error("System Property not found: " + propertyName);
        return '{}'; // Return empty JSON if not found
    }
});
